function fetchUser(id) {
  return new Promise((resolve, reject) => {
    if (id > 0) {
      resolve({ id, name: 'Ada' });
    } else {
      reject(new Error('invalid id'));
    }
  });
}

fetchUser(1)
  .then((user) => {
    console.log('resolved:', user.name);
    return user.id;
  })
  .then((id) => console.log('chained id:', id))
  .catch((err) => console.log('error:', err.message))
  .finally(() => console.log('done: fetchUser(1)'));

fetchUser(-1)
  .then((user) => console.log('resolved:', user.name))
  .catch((err) => console.log('error:', err.message))
  .finally(() => console.log('done: fetchUser(-1)'));
